// Verify X-DG-Signature = sha256=HMAC_SHA256(secret, "<ts>.<raw body>") and output the parsed body.
// The raw bytes matter: the service signs canonical JSON (sorted keys, compact separators, floats
// like 125000.0), which a re-serialisation in JavaScript would not reproduce.
const crypto = require('crypto');

let secret;
try {
  secret = $env.DG_N8N_SHARED_SECRET;
} catch (e) {
  throw new Error('n8n blocks $env in this build. Set N8N_BLOCK_ENV_ACCESS_IN_NODE="false" on the n8n container. (' + e.message + ')');
}
if (!secret) {
  throw new Error('DG_N8N_SHARED_SECRET is empty or not set on the n8n container.');
}

const item = $input.first();
const headers = item.json.headers || {};
const ts = String(headers['x-dg-timestamp'] || '');
const sig = String(headers['x-dg-signature'] || '');

if (!/^\d+$/.test(ts)) {
  throw new Error('Rejected: missing or malformed X-DG-Timestamp');
}
const skew = Math.abs(Math.floor(Date.now() / 1000) - Number(ts));
if (skew > 300) {
  throw new Error('Rejected: X-DG-Timestamp is ' + skew + 's away from now (limit 300s)');
}

// Raw body bytes come from the Webhook node option "Raw Body" (binary property "data").
const h = (typeof helpers === 'object' && helpers) || (this && this.helpers);
let raw;
try {
  raw = await h.getBinaryDataBuffer(0, 'data');
} catch (e) {
  const inline = item.binary && item.binary.data && item.binary.data.data;
  if (!inline) {
    throw new Error('Rejected: raw body unavailable. Enable "Raw Body" on the Webhook node. (' + e.message + ')');
  }
  raw = Buffer.from(inline, 'base64');
}

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest('hex');
const a = Buffer.from(sig, 'utf8');
const b = Buffer.from(expected, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Rejected: X-DG-Signature mismatch');
}

const body = JSON.parse(raw.toString('utf8'));
return [{ json: body }];

// Turn the service's approval_card notification into a Slack card.
// Outputs: blocks (Block Kit, for a plain Send node), text (mrkdwn, what Send and Wait renders),
// and the fields later nodes need. Every value comes from the service; n8n derives nothing.
const n = $input.first().json;
if (n.kind !== 'approval_card') {
  throw new Error('Expected kind approval_card, got ' + n.kind);
}
const p = n.payload || {};

const esc = (v) => String(v === null || v === undefined ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const usd = (v) => {
  const num = Number(v);
  if (!Number.isFinite(num)) return 'n/a';
  const parts = num.toFixed(2).split('.');
  return '$' + parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',') + '.' + parts[1];
};
const pct = (v) => (v === null || v === undefined || v === '') ? 'n/a' : v + '%';

const requester = p.requester || {};
const requesterLine = [requester.name, requester.title].filter(Boolean).map(esc).join(', ') || 'unknown';
const gateIds = Array.isArray(p.gate_slack_user_ids) ? p.gate_slack_user_ids.filter(Boolean) : [];
const gateNames = Array.isArray(p.gate_names) ? p.gate_names : [];
const mentions = gateIds.map((id) => '<@' + id + '>').join(' ');
const gateLabel = p.gate_label || p.gate_role || 'gate approver';
const waitingOn = mentions || esc(gateNames.join(', ')) || 'no approver on file';

const requiredLines = (Array.isArray(p.required) ? p.required : []).map((r) => {
  const isGate = r.is_gate === true || (p.gate_role && r.role === p.gate_role);
  return '• ' + esc(r.label || r.role) + (isGate ? ' — decides (this card)' : ' — also required');
});
if (requiredLines.length === 0) requiredLines.push('• none listed');

const ruleLines = (Array.isArray(p.rules_fired) ? p.rules_fired : [])
  .map((r) => '• ' + esc(r.why || (r.id + ': ' + (r.effect || r.title))));
if (ruleLines.length === 0) ruleLines.push('• none');

const unresolved = Array.isArray(p.unresolved) ? p.unresolved : [];
const unresolvedLines = unresolved.map((u) => '*The policy does not settle this, so Deal Desk decides: ' + esc(u.short) + ' [' + esc(u.id) + ']*');
const flags = Array.isArray(p.flags) ? p.flags : [];

const title = p.deal_id + ' · ' + (p.account || 'unknown account');
const summary = 'List total ' + usd(p.list_total_usd) + ' · Discount ' + pct(p.discount_percent)
  + ' · Net ' + usd(p.net_total_usd) + ' · Term ' + (p.term_months === null || p.term_months === undefined ? 'n/a' : p.term_months) + ' months'
  + ' · Payment ' + esc(p.payment_terms) + ' · Segment ' + esc(p.segment);

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: title.slice(0, 150), emoji: false } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*List total*\n' + usd(p.list_total_usd) },
    { type: 'mrkdwn', text: '*Discount*\n' + pct(p.discount_percent) },
    { type: 'mrkdwn', text: '*Net*\n' + usd(p.net_total_usd) },
    { type: 'mrkdwn', text: '*Term*\n' + (p.term_months === null || p.term_months === undefined ? 'n/a' : p.term_months) + ' months' },
    { type: 'mrkdwn', text: '*Payment terms*\n' + esc(p.payment_terms) },
    { type: 'mrkdwn', text: '*Segment*\n' + esc(p.segment) },
    { type: 'mrkdwn', text: '*Requester*\n' + requesterLine },
  ] },
  { type: 'section', text: { type: 'mrkdwn', text: '*Sign-off needed from*\n' + requiredLines.join('\n') } },
  { type: 'section', text: { type: 'mrkdwn', text: '*Why this needs approval*\n' + ruleLines.join('\n') } },
];
if (unresolvedLines.length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: unresolvedLines.join('\n') } });
}
const contextElements = [];
if (p.receipt_url) contextElements.push({ type: 'mrkdwn', text: '<' + p.receipt_url + '|Open receipt>' });
if (flags.length) contextElements.push({ type: 'mrkdwn', text: 'Flags: ' + flags.map(esc).join(', ') });
if (contextElements.length) blocks.push({ type: 'context', elements: contextElements });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: 'Waiting on ' + waitingOn + ' (' + esc(gateLabel) + ')' } });

// Plain mrkdwn version. Send and Wait renders only this (one section block plus its buttons).
const textLines = [
  '*' + esc(title) + '*',
  summary,
  'Requester: ' + requesterLine,
  '*Sign-off needed from*',
  ...requiredLines,
  '*Why this needs approval*',
  ...ruleLines,
  ...unresolvedLines,
  ...(flags.length ? ['Flags: ' + flags.map(esc).join(', ')] : []),
  'Waiting on ' + waitingOn + ' (' + esc(gateLabel) + ')',
  ...(p.receipt_url ? ['<' + p.receipt_url + '|Open receipt>'] : []),
];
const text = textLines.join('\n').slice(0, 2900);

return [{ json: {
  notification_id: n.notification_id,
  deal_id: p.deal_id,
  account: p.account,
  gate_role: p.gate_role,
  gate_label: p.gate_label,
  gate_slack_user_ids: gateIds,
  // The card is a direct message to the one person who must decide. Deal terms never reach a
  // shared channel. With more than one holder of the gate role this takes the first; fanning a
  // card out to several waiting nodes is left undone deliberately.
  gate_dm_user_id: gateIds[0] || '',
  gate_names: gateNames,
  receipt_url: p.receipt_url,
  requester: requester,
  thread: p.thread || null,
  blocks: blocks,
  text: text,
} }];

// Build and sign the approval event for POST /events/approval.
// The service re-reads the deal row and decides whether this click counts; n8n only reports it.
const crypto = require('crypto');

let secret;
try {
  secret = $env.DG_N8N_SHARED_SECRET;
} catch (e) {
  throw new Error('n8n blocks $env in this build. Set N8N_BLOCK_ENV_ACCESS_IN_NODE="false" on the n8n container. (' + e.message + ')');
}
if (!secret) {
  throw new Error('DG_N8N_SHARED_SECRET is empty or not set on the n8n container.');
}

const resp = ($input.first().json || {}).data || {};
const card = $('Build Block Kit').first().json;

if (typeof resp.approved !== 'boolean') {
  throw new Error('No decision in the Send and Wait output (data.approved missing). Nothing was sent to the service.');
}
const responderId = resp.responder && resp.responder.id;
if (!responderId) {
  // Deliberately no fallback to the first gate approver: an unattributed click must not become
  // a recorded decision. Enable "Capture Who Responded" and the Slack app Interactivity URL.
  throw new Error('Slack did not report who clicked (data.responder.id missing). Not sending an unattributed decision.');
}

const payload = {
  deal_id: card.deal_id,
  slack_user_id: responderId,
  decision: resp.approved === true ? 'approve' : 'reject',
  slack_message_ts: resp.messageId ? String(resp.messageId) : null,
  responded_at: resp.respondedAt || new Date().toISOString(),
};
const body = JSON.stringify(payload); // exactly what the HTTP Request node sends, byte for byte
const ts = String(Math.floor(Date.now() / 1000));
const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + body, 'utf8').digest('hex');

return [{ json: {
  body: body,
  ts: ts,
  sig: sig,
  deal_id: card.deal_id,
  decision: payload.decision,
  responder: resp.responder,
  channel: resp.channel,
  message_ts: payload.slack_message_ts,
  responded_at: payload.responded_at,
} }];

